import{_ as p,a0 as a,w as d,s as r,ao as l,I as n,x as e,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"用这个开源工具在 Linux 上访问你的 iPhone | LCTT x X-CMD","titleTemplate":false,"description":"用这个开源工具在 Linux 上访问你的 iPhone | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用这个开源工具在 Linux 上访问你的 iPhone | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用这个开源工具在 Linux 上访问你的 iPhone | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210823 Access your iPhone on Linux with this open source tool","title":"用这个开源工具在 Linux 上访问你的 iPhone","tag":"202108","desc":""},"relativePath":"202108/20210823 Access your iPhone on Linux with this open source tool.md","filePath":"[post].md"}'),u={name:"202108/20210823 Access your iPhone on Linux with this open source tool.md"};function b(h,i,m,g,c,k){const t=a("Link");return d(),r("div",null,[i[24]||(i[24]=l('<h1 id="用这个开源工具在-linux-上访问你的-iphone" tabindex="-1">用这个开源工具在 Linux 上访问你的 iPhone <a class="header-anchor" href="#用这个开源工具在-linux-上访问你的-iphone" aria-label="Permalink to “用这个开源工具在 Linux 上访问你的 iPhone”">​</a></h1><blockquote><p>通过使用 Libimobiledevice 从 Linux 与 iOS 设备进行通信。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/31/092907bc26qep3ekc73czl.jpg" alt=""></p><p>iPhone 和 iPad 绝不是开源的，但它们是流行的设备。许多拥有 iOS 备的人恰好也在使用大量的开源软件，包括 Linux。Windows 和 macOS 的用户可以通过使用苹果公司提供的软件与 iOS 设备通信，但苹果公司不支持 Linux 用户。开源程序员早在 2007 年（就在 iPhone 发布一年后）就以 Libimobiledevice（当时叫 libiphone）来拯救了人们，这是一个与 iOS 通信的跨平台解决方案。它可以在 Linux、Android、Arm 系统（如树莓派）、Windows、甚至 macOS 上运行。</p><p>Libimobiledevice 是用 C 语言编写的，使用原生协议与 iOS 设备上运行的服务进行通信。它不需要苹果公司的任何库，所以它完全是自由而开源的。</p><p>Libimobiledevice 是一个面向对象的 API，它捆绑了许多便于你使用的终端工具。该库支持苹果从最早到其最新的型号的 iOS 设备。这是多年来研究和开发的结果。该项目中的应用包括 <code>usbmuxd</code>、<code>ideviceinstaller</code>、<code>idevicerestore</code>、<code>ifuse</code>、<code>libusbmuxd</code>、<code>libplist</code>、<code>libirecovery</code> 和 <code>libideviceactivation</code>。</p><h3 id="在-linux-上安装-libimobiledevice" tabindex="-1">在 Linux 上安装 Libimobiledevice <a class="header-anchor" href="#在-linux-上安装-libimobiledevice" aria-label="Permalink to “在 Linux 上安装 Libimobiledevice”">​</a></h3><p>在 Linux 上，你可能已经默认安装了 <code>libimobiledevice</code>。你可以通过你的软件包管理器或应用商店找到，或者通过运行项目中包含的一个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifuse --help</span></span></code></pre></div><p>你可以用你的包管理器安装 <code>libimobiledevice</code>。例如，在 Fedora 或 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install libimobiledevice ifuse usbmuxd</span></span></code></pre></div><p>在 Debian 和 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install usbmuxd libimobiledevice6 libimobiledevice-utils</span></span></code></pre></div>',13)),n("p",null,[i[1]||(i[1]=e("或者，你可以从源代码 ",-1)),s(t,{href:"https://github.com/libimobiledevice/libimobiledevice/"},{default:o(()=>[...i[0]||(i[0]=[e("下载",-1)])]),_:1}),i[2]||(i[2]=e(" 并安装 ",-1)),i[3]||(i[3]=n("code",null,"libimobiledevice",-1)),i[4]||(i[4]=e("。",-1))]),i[25]||(i[25]=l('<h3 id="连接你的设备" tabindex="-1">连接你的设备 <a class="header-anchor" href="#连接你的设备" aria-label="Permalink to “连接你的设备”">​</a></h3><p>当你安装了所需的软件包，将你的 iOS 设备连接到你的电脑。</p><p>为你的 iOS 设备建立一个目录作为挂载点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/iPhone</span></span></code></pre></div><p>接下来，挂载设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifuse ~/iPhone</span></span></code></pre></div><p>你的设备提示你，是否信任你用来访问它的电脑。</p><p><img src="https://opensource.com/sites/default/files/1trust_0.png" alt="iphone prompts to trust the computer"></p><p><em>图 1：iPhone 提示你要信任该电脑。</em></p><p>信任问题解决后，你会在桌面上看到新的图标。</p><p><img src="https://opensource.com/sites/default/files/2docks.png" alt="iphone icons appear on desktop"></p><p><em>图 2：iPhone 的新图标出现在桌面上。</em></p><p>点击 “iPhone” 图标，显示出你的 iPhone 的文件夹结构。</p><p><img src="https://opensource.com/sites/default/files/2iphoneicon.png" alt="iphone folder structure displayed"></p><p><em>图 3：显示了 iPhone 的文件夹结构。</em></p><p>我通常最常访问的文件夹是 <code>DCIM</code>，那里存放着我的 iPhone 照片。有时我在写文章时使用这些照片，有时有一些照片我想用 GIMP 等开源应用来增强。可以直接访问这些图片，而不是通过电子邮件把它们发给我自己，这是使用 <code>libimobiledevice</code> 工具的好处之一。我可以把这些文件夹中的任何一个复制到我的 Linux 电脑上。我也可以在 iPhone 上创建文件夹并删除它们。</p><h3 id="发现更多" tabindex="-1">发现更多 <a class="header-anchor" href="#发现更多" aria-label="Permalink to “发现更多”">​</a></h3>',17)),n("p",null,[s(t,{href:"https://github.com/FunkyM"},{default:o(()=>[...i[5]||(i[5]=[e("Martin Szulecki",-1)])]),_:1}),i[7]||(i[7]=e(" 是该项目的首席开发者。该项目正在寻找开发者加入他们的 ",-1)),s(t,{href:"https://libimobiledevice.org/#community"},{default:o(()=>[...i[6]||(i[6]=[e("社区",-1)])]),_:1}),i[8]||(i[8]=e("。Libimobiledevice 可以改变你使用外设的方式，而无论你在什么平台上。这是开源的又一次胜利，这意味着它是所有人的胜利。",-1))]),i[26]||(i[26]=n("hr",null,null,-1)),n("p",null,[i[10]||(i[10]=e("via: ",-1)),s(t,{href:"https://opensource.com/article/21/8/libimobiledevice-iphone-linux"},{default:o(()=>[...i[9]||(i[9]=[e("https://opensource.com/article/21/8/libimobiledevice-iphone-linux",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=e("作者：",-1)),s(t,{href:"https://opensource.com/users/don-watkins"},{default:o(()=>[...i[11]||(i[11]=[e("Don Watkins",-1)])]),_:1}),i[16]||(i[16]=e(" 选题：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...i[12]||(i[12]=[e("lujun9972",-1)])]),_:1}),i[17]||(i[17]=e(" 译者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:o(()=>[...i[13]||(i[13]=[e("geekpi",-1)])]),_:1}),i[18]||(i[18]=e(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:o(()=>[...i[14]||(i[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[i[21]||(i[21]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[19]||(i[19]=[e("LCTT",-1)])]),_:1}),i[22]||(i[22]=e(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:o(()=>[...i[20]||(i[20]=[e("Linux中国",-1)])]),_:1}),i[23]||(i[23]=e(" 荣誉推出",-1))])])}const L=p(u,[["render",b]]);export{v as __pageData,L as default};
